// Star Wars Episode I Racer (GOG) mod installer.
// Builds SWEP1RCR.EXE from the untouched GOG exe with any combination of the mods in
// PatchData.cs (generated by gen.py), and makes the matching changes to three data files.
// The untouched exe is always kept as "SWEP1RCR.EXE.original", so options can be changed later.
using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Text.RegularExpressions;
using System.Windows.Forms;

class Option {
    public string Key, Title, Info;
    public CheckBox Box;
}

class InstallerForm : Form {
    const string ExeName = "SWEP1RCR.EXE";
    const string BackupName = "SWEP1RCR.EXE.original";
    const string HdBackupName = "SWEP1RCR.EXE.orig";           // made by the SWE1R HD Redraw installer
    const string SpritesPath = @"data\lev01\out_spriteblock.bin";
    const string SoundsPath = @"data\Sounds.map";
    const string ControlsPath = @"data\config\current\current_control.map";
    const string ModelsPath = @"data\lev01\out_modelblock.bin";
    const int SpriteSize = 4644, StockSprites = 179;
    static readonly Encoding Latin1 = Encoding.GetEncoding(28591);

    static readonly Dictionary<string, KeyValuePair<int, byte[]>[]> Runs = LoadRuns();

    readonly TextBox folder = new TextBox();
    readonly Label status = new Label();
    readonly TextBox info = new TextBox();
    readonly List<Option> options = new List<Option>();
    readonly Button install = new Button(), restore = new Button();
    byte[] baseExe;          // stock GOG exe, LAA bit clear
    byte[] curExe;
    bool hdRedraw;

    Option Opt(string key) { return options.First(o => o.Key == key); }
    bool On(string key) { return Opt(key).Box.Checked; }
    void Set(string key, bool v) { Opt(key).Box.Checked = v; }

