    GroupBox Group(Control parent, string title) {
        var g = new GroupBox { Text = title, AutoSize = true, AutoSizeMode = AutoSizeMode.GrowAndShrink, Width = 640, MinimumSize = new Size(640, 0), Padding = new Padding(8, 4, 8, 6) };
        var p = new FlowLayoutPanel { FlowDirection = FlowDirection.TopDown, AutoSize = true, AutoSizeMode = AutoSizeMode.GrowAndShrink, WrapContents = false, Location = new Point(8, 20) };
        g.Controls.Add(p);
        parent.Controls.Add(g);
        return g;
    }

    void Check(GroupBox g, string key, string title, string text) {
        var c = new CheckBox { Text = title.TrimStart(), AutoSize = true };
        if (title.StartsWith(" ")) c.Margin = new Padding(20, c.Margin.Top, c.Margin.Right, c.Margin.Bottom);
        g.Controls[0].Controls.Add(c);
        var o = new Option { Key = key, Title = title.Trim(), Info = text, Box = c };
        c.MouseEnter += (s, e) => info.Text = o.Title + "\r\n\r\n" + o.Info;
        c.GotFocus += (s, e) => info.Text = o.Title + "\r\n\r\n" + o.Info;
        options.Add(o);
    }

    void UpdateEnabled() {
        bool ok = baseExe != null;
        foreach (var o in options) o.Box.Enabled = ok;
        Opt("freeplay").Box.Enabled = ok && On("split");
        if (hdRedraw) { Set("laa", true); Opt("laa").Box.Enabled = false; }
    }

    // ---- patch data ----

    static byte[] Hex(string h) {
        var b = new byte[h.Length / 2];
        for (int i = 0; i < b.Length; i++) b[i] = Convert.ToByte(h.Substring(i * 2, 2), 16);
        return b;
    }

    static Dictionary<string, KeyValuePair<int, byte[]>[]> LoadRuns() {
        var d = new Dictionary<string, KeyValuePair<int, byte[]>[]>();
        foreach (var g in PatchData.Runs) {
            var l = new List<KeyValuePair<int, byte[]>>();
            for (int i = 1; i < g.Length; i += 2) l.Add(new KeyValuePair<int, byte[]>((int)g[i], Hex((string)g[i + 1])));
            d[(string)g[0]] = l.ToArray();
        }
        return d;
    }

    static bool IsIn(string key, byte[] exe) {
        foreach (var r in Runs[key]) {
            if (r.Key + r.Value.Length > exe.Length) return false;
            for (int i = 0; i < r.Value.Length; i++) if (exe[r.Key + i] != r.Value[i]) return false;
        }
        return true;
    }

    static string Md5(byte[] b) {
        using (var m = MD5.Create()) return BitConverter.ToString(m.ComputeHash(b)).Replace("-", "");
    }

    // the stock exe, with or without the LAA bit HD Redraw sets: returns it with the bit clear, or null
    static byte[] AsStock(byte[] b) {
        if (b == null || b.Length != PatchData.StockLength) return null;
        var c = (byte[])b.Clone();
        c[PatchData.LaaOffset] &= unchecked((byte)~0x20);
        return Md5(c) == PatchData.StockMd5 ? c : null;
    }

    static byte[] TryRead(string path) {
        try { return File.Exists(path) ? File.ReadAllBytes(path) : null; } catch { return null; }
    }

    string Dir { get { return folder.Text.Trim().Trim('"'); } }

    void LoadFolder() {
        baseExe = curExe = null;
        string dir = Dir, exe = Path.Combine(dir, ExeName);
        install.Enabled = restore.Enabled = false;
        foreach (var o in options) o.Box.Enabled = false;
        if (dir.Length == 0 || !File.Exists(exe)) {
            status.ForeColor = Color.DarkRed;
            status.Text = dir.Length == 0 ? "Choose the folder where Star Wars Episode I Racer is installed."
                                          : "\"" + ExeName + "\" was not found in that folder.";
            return;
        }
        try { curExe = File.ReadAllBytes(exe); }
        catch (Exception ex) { status.ForeColor = Color.DarkRed; status.Text = "Can't read the exe: " + ex.Message; return; }
        hdRedraw = File.Exists(Path.Combine(dir, "swe1r_hd.ini")) && File.Exists(Path.Combine(dir, "dinput.dll"));

        bool clean = false;
        string hd = hdRedraw ? " SWE1R HD Redraw was found, so Large Address Aware stays on." : "";
        if ((baseExe = AsStock(curExe)) != null) {
            clean = true;
            status.ForeColor = Color.DarkGreen;
            status.Text = "Found the GOG exe. It will be backed up as \"" + BackupName + "\" before patching." + hd;
        } else if ((baseExe = AsStock(TryRead(Path.Combine(dir, BackupName)))) != null ||
                   (baseExe = AsStock(TryRead(Path.Combine(dir, HdBackupName)))) != null) {
            status.ForeColor = Color.DarkGreen;
            status.Text = "The exe is already modified. The installer will rebuild it from the untouched GOG exe kept beside it. " +
                          "The ticked options show what's installed now." + hd;
        } else {
            status.ForeColor = Color.DarkRed;
            status.Text = "This isn't the GOG version's exe (MD5 " + PatchData.StockMd5 + "), and there's no untouched copy as \"" +
                          BackupName + "\". Reinstall the game or restore the original exe, then try again.";
            return;
        }
        install.Enabled = true;
        restore.Enabled = true;

        // reflect what is installed now (defaults for a clean exe)
        foreach (var k in PatchData.Keys) Set(k, clean || IsIn(k, curExe));
        Set("freeplay", !clean && IsIn("split", curExe) && curExe.Length > PatchData.FreePlayRecordsOffset &&
                        curExe[PatchData.FreePlayRecordsOffset] == 1);
        Set("laa", clean || (curExe[PatchData.LaaOffset] & 0x20) != 0);
        string ctl = ReadText(Path.Combine(dir, ControlsPath));
        Set("enter", ctl != null && !HasEnterThrust(ctl));
        bool rockIn = false;
        try { byte[] mb = TryRead(Path.Combine(dir, ModelsPath)); rockIn = mb != null && RockFix.IsApplied(mb); } catch { }
        Set("rock", rockIn || (clean && hdRedraw));
        UpdateEnabled();
    }

    byte[] BuildExe(List<string> applied) {
        var keys = PatchData.Keys.Where(On).ToList();
        byte[] img;
        if (keys.Count == 0) img = (byte[])baseExe.Clone();
        else {
            img = new byte[PatchData.ModdedLength];
            Buffer.BlockCopy(baseExe, 0, img, 0, baseExe.Length);
            var hdr = Hex(PatchData.Header);
            Buffer.BlockCopy(hdr, 0, img, 0, hdr.Length);
            foreach (var k in keys) {
                foreach (var r in Runs[k]) Buffer.BlockCopy(r.Value, 0, img, r.Key, r.Value.Length);
                applied.Add(Opt(k).Title);
            }
            if (keys.Contains("split") && On("freeplay")) { img[PatchData.FreePlayRecordsOffset] = 1; applied.Add("Free Play sets track records"); }
        }
        if (On("laa")) { img[PatchData.LaaOffset] |= 0x20; applied.Add(Opt("laa").Title); }
        // every mod on with the default options must come out as the tested build
        if (keys.Count == PatchData.Keys.Length && On("laa") && !On("freeplay") && Md5(img) != PatchData.AllOnMd5)
            throw new InvalidOperationException("The patched exe came out wrong. Nothing was changed.");
        return img;
    }

    // ---- data files ----

    static string ReadText(string path) {
        try { return File.Exists(path) ? Latin1.GetString(File.ReadAllBytes(path)) : null; } catch { return null; }
    }

    static uint BE(byte[] a, int o) { return ((uint)a[o] << 24) | ((uint)a[o + 1] << 16) | ((uint)a[o + 2] << 8) | a[o + 3]; }
    static void PutBE(byte[] a, int o, uint v) { a[o] = (byte)(v >> 24); a[o + 1] = (byte)(v >> 16); a[o + 2] = (byte)(v >> 8); a[o + 3] = (byte)v; }

    // returns the new file, or null when nothing needs changing
    static byte[] Sprites(byte[] o, bool want) {
        uint n = BE(o, 0);
        if (n == StockSprites) {
            if (BE(o, 4) != 4 + 180 * 4 || BE(o, 4 + 179 * 4) != (uint)o.Length) throw new InvalidOperationException("out_spriteblock.bin isn't laid out as expected.");
            if (!want) return null;
            byte[] j = Hex(PatchData.JinnSprite), c = Hex(PatchData.CySprite);
            var w = new byte[o.Length + 8 + j.Length + c.Length];
            PutBE(w, 0, 181);
            for (int i = 0; i < 180; i++) PutBE(w, 4 + 4 * i, BE(o, 4 + 4 * i) + 8);
            uint end = (uint)o.Length + 8;
            PutBE(w, 4 + 4 * 180, end + (uint)j.Length);
            PutBE(w, 4 + 4 * 181, end + (uint)(j.Length + c.Length));
            Array.Copy(o, 4 + 180 * 4, w, 4 + 182 * 4, o.Length - (4 + 180 * 4));
            Array.Copy(j, 0, w, (int)end, j.Length);
            Array.Copy(c, 0, w, (int)end + j.Length, c.Length);
            return w;
        }
        if (n == StockSprites + 2) {
            uint a = BE(o, 4 + 4 * 179), z = BE(o, 4 + 4 * 181);
            if (BE(o, 4) != 4 + 182 * 4 || z != (uint)o.Length || z - a != 2 * SpriteSize) throw new InvalidOperationException("out_spriteblock.bin isn't laid out as expected.");
            if (want) return null;          // portraits already there
            var w = new byte[a - 8];
            PutBE(w, 0, StockSprites);
            for (int i = 0; i < 180; i++) PutBE(w, 4 + 4 * i, BE(o, 4 + 4 * i) - 8);
            Array.Copy(o, 4 + 182 * 4, w, 4 + 180 * 4, (int)a - (4 + 182 * 4));
            return w;
        }
        throw new InvalidOperationException("out_spriteblock.bin has " + n + " images, not the game's 179.");
    }

    static string Sounds(string text, bool want) {
        string nl = text.Contains("\r\n") ? "\r\n" : "\n";
        var lines = Regex.Split(text, "\r?\n");
        var idx = new List<int>();
        for (int i = 0; i < lines.Length; i++) if (!Regex.IsMatch(lines[i], @"^\s*(#|NUMSOUNDS|$)")) idx.Add(i);
        if (idx.Count < 0xB4 || !lines[idx[0xAA]].Contains("chop_a_combo") || !lines[idx[0xAD]].Contains("varispeed_comb"))
            throw new InvalidOperationException("data\\Sounds.map isn't as expected.");
        bool patched = true, stock = true;
        for (int k = 0; k < 4; k++) {
            if (lines[idx[0xB0 + k]] != lines[idx[0xAA + k]]) patched = false;
            if (lines[idx[0xB0 + k]] != PatchData.StockSoundsB0[k]) stock = false;
        }
        if (want == patched) return null;
        if (!want && !stock) for (int k = 0; k < 4; k++) lines[idx[0xB0 + k]] = PatchData.StockSoundsB0[k];
        if (want) for (int k = 0; k < 4; k++) lines[idx[0xB0 + k]] = lines[idx[0xAA + k]];
        return string.Join(nl, lines);
    }

    const string EnterLine = @"(?m)^[ \t]*KEYBOARD[ \t]+KEY=ENTER[ \t]+FUNCTION=THRUST[ \t]*\r?\n";
    static bool HasEnterThrust(string t) { return Regex.IsMatch(t, EnterLine); }

    static string ControlMap(string text, bool removeEnter) {
        bool has = HasEnterThrust(text);
        if (removeEnter) {
            if (!has) return null;
            string n = Regex.Replace(text, EnterLine, "");
            if (!n.Contains("FUNCTION=THRUST")) throw new InvalidOperationException("Removing Enter would leave no Thrust binding.");
            return n;
        }
        if (has) return null;
        var w = Regex.Match(text, @"(?m)^[ \t]*KEYBOARD[ \t]+KEY=W[ \t]+FUNCTION=THRUST[ \t]*(\r?\n)");
        if (!w.Success) return null;        // custom controls: leave them alone
        string line = "KEYBOARD".PadRight(28) + "KEY=ENTER".PadRight(28) + "FUNCTION=THRUST".PadRight(56) + w.Groups[1].Value;
        return text.Insert(w.Index + w.Length, line);
    }

    // ---- writing ----

    bool GameRunning() {
#if TESTCLI
        return false;       // the test build only ever works on scratch folders
#endif
        try { return Process.GetProcesses().Any(p => { try { return p.ProcessName.StartsWith("SWEP1RCR", StringComparison.OrdinalIgnoreCase); } catch { return false; } }); }
        catch { return false; }
    }

    void Apply(bool restoreAll) {
        if (baseExe == null) return;
        if (GameRunning()) { Ask("Close the game first.", Text, MessageBoxButtons.OK, MessageBoxIcon.Warning); return; }
        string dir = Dir;
        bool wantExtra = !restoreAll && On("extra"), wantSplit = !restoreAll && On("split"), wantEnter = !restoreAll && On("enter");
        bool wantRock = !restoreAll && On("rock");
        string mp = Path.Combine(dir, ModelsPath);
        byte[] models = TryRead(mp);
        bool rockIn = false;
        try { rockIn = models != null && RockFix.IsApplied(models); } catch { }
        if (wantRock && !rockIn && !hdRedraw &&
            Ask("SWE1R HD Redraw isn't installed in this folder. Its installer only accepts the untouched model file, so if you " +
                "plan to install HD Redraw, choose No, install HD Redraw first, then run this installer again.\r\n\r\n" +
                "Add the Executioner rock fix to the stock model file now?", Text, MessageBoxButtons.YesNo, MessageBoxIcon.Warning) != DialogResult.Yes) return;
        if (!restoreAll && IsIn("extra", curExe) && !wantExtra &&
            Ask("This removes Jinn Reeso and Cy Yunga. If a profile is set to either of them, pick a stock pilot in " +
                "the game first. Records set by Jinn or Cy will show the wrong racer.\r\n\r\nContinue?", Text,
                MessageBoxButtons.YesNo, MessageBoxIcon.Warning) != DialogResult.Yes) return;

        var applied = new List<string>();
        var notes = new List<string>();
        var writes = new List<KeyValuePair<string, byte[]>>();
        var backups = new List<KeyValuePair<string, string>>();       // file -> its first backup name
        try {
            byte[] img;
            if (restoreAll) {
                img = (byte[])baseExe.Clone();
                if (hdRedraw) { img[PatchData.LaaOffset] |= 0x20; notes.Add("Large Address Aware was kept on for SWE1R HD Redraw."); }
            } else img = BuildExe(applied);
            writes.Add(new KeyValuePair<string, byte[]>(Path.Combine(dir, ExeName), img));

            string sp = Path.Combine(dir, SpritesPath);
            byte[] sb = TryRead(sp);
            if (sb == null) { if (wantExtra) throw new InvalidOperationException("data\\lev01\\out_spriteblock.bin wasn't found, so Jinn and Cy's portraits can't be added."); }
            else {
                byte[] ns = Sprites(sb, wantExtra);
                if (ns != null) {
                    writes.Add(new KeyValuePair<string, byte[]>(sp, ns));
                    if (wantExtra) backups.Add(new KeyValuePair<string, string>(sp, sp + ".original"));
                    notes.Add(wantExtra ? "Jinn and Cy's portraits were added to out_spriteblock.bin." : "Jinn and Cy's portraits were removed from out_spriteblock.bin.");
                }
            }

            string so = Path.Combine(dir, SoundsPath);
            string st = ReadText(so);
            if (st == null) { if (wantSplit) notes.Add("data\\Sounds.map wasn't found, so player 2 uses the stock engine sounds."); }
            else {
                string ns = Sounds(st, wantSplit);
                if (ns != null) {
                    writes.Add(new KeyValuePair<string, byte[]>(so, Latin1.GetBytes(ns)));
                    if (wantSplit) backups.Add(new KeyValuePair<string, string>(so, so + ".original"));
                    notes.Add(wantSplit ? "Player 2's engine sounds were set in Sounds.map." : "Sounds.map was put back to the stock engine sounds.");
                }
            }

            if (models == null) { if (wantRock) throw new InvalidOperationException("data\\lev01\\out_modelblock.bin wasn't found, so the Executioner rock fix can't be added."); }
            else if (wantRock != rockIn) {
                byte[] nm;
                try { nm = wantRock ? RockFix.Apply(models) : RockFix.Remove(models); }
                catch (InvalidOperationException ex) {
                    if (wantRock) throw;
                    nm = null; notes.Add("The Executioner rock fix couldn't be taken out: " + ex.Message);
                }
                if (nm != null) {
                    writes.Add(new KeyValuePair<string, byte[]>(mp, nm));
                    notes.Add(wantRock ? "The Executioner rock fix was added to out_modelblock.bin." : "The Executioner rock fix was taken out of out_modelblock.bin.");
                }
            }
            if (wantRock) applied.Add(Opt("rock").Title);

            string co = Path.Combine(dir, ControlsPath);
            string ct = ReadText(co);
            if (ct == null) { if (wantEnter) notes.Add("Your controls file wasn't found, so the Enter binding wasn't changed."); }
            else {
                string nc = ControlMap(ct, wantEnter);
                if (nc != null) {
                    writes.Add(new KeyValuePair<string, byte[]>(co, Latin1.GetBytes(nc)));
                    notes.Add(wantEnter ? "Enter no longer counts as Thrust; skip the intro with Escape." : "Enter is bound to Thrust again.");
                }
                if (wantEnter) applied.Add(Opt("enter").Title);
            }
        } catch (Exception ex) {
            Ask(ex.Message + "\r\n\r\nNothing was changed.", Text, MessageBoxButtons.OK, MessageBoxIcon.Error);
            return;
        }

        string exe = Path.Combine(dir, ExeName), bak = Path.Combine(dir, BackupName);
        try {
            // a file already using the backup name that isn't the untouched exe is moved aside, never overwritten
            byte[] old = TryRead(bak);
            if (old != null && Md5(old) != PatchData.StockMd5) {
                string moved = Path.Combine(dir, "SWEP1RCR.EXE.original-old");
                for (int i = 2; File.Exists(moved); i++) moved = Path.Combine(dir, "SWEP1RCR.EXE.original-old" + i);
                File.Move(bak, moved);
                notes.Add("The file that was already called \"" + BackupName + "\" wasn't the untouched exe, so it was renamed to \"" + Path.GetFileName(moved) + "\".");
            }
            if (!File.Exists(bak)) File.WriteAllBytes(bak, baseExe);
            foreach (var b in backups) if (!File.Exists(b.Value)) File.Copy(b.Key, b.Value);
            foreach (var w in writes) {
                File.WriteAllBytes(w.Key + ".tmp", w.Value);
                File.Copy(w.Key + ".tmp", w.Key, true);
                File.Delete(w.Key + ".tmp");
            }
        } catch (Exception ex) {
            foreach (var w in writes) try { File.Delete(w.Key + ".tmp"); } catch { }
            string why = ex is UnauthorizedAccessException
                ? "Windows denied access to the game folder. Right-click the installer and choose \"Run as administrator\"."
                : "Couldn't write the game files. Close the game if it's running and try again.";
            Ask(why + "\r\n\r\n" + ex.Message, Text, MessageBoxButtons.OK, MessageBoxIcon.Error);
            LoadFolder();
            return;
        }

        string msg;
        if (restoreAll) msg = "The original game is back. Every mod is removed.";
        else msg = applied.Count == 0 ? "No options were selected, so the exe is now the original." : "Installed:\r\n  - " + string.Join("\r\n  - ", applied);
        if (notes.Count > 0) msg += "\r\n\r\n" + string.Join("\r\n", notes);
        msg += "\r\n\r\nYour untouched exe is kept as \"" + BackupName + "\". Always run the game as administrator.";
        Ask(msg, Text, MessageBoxButtons.OK, MessageBoxIcon.Information);
        LoadFolder();
    }

    static bool silent;     // test build only: dialogs are logged and answered Yes / OK
    DialogResult Ask(string text, string caption, MessageBoxButtons buttons, MessageBoxIcon icon) {
        if (silent) { Console.WriteLine("[" + icon + "] " + text.Replace("\r\n", " | ")); return buttons == MessageBoxButtons.YesNo ? DialogResult.Yes : DialogResult.OK; }
        return MessageBox.Show(this, text, caption, buttons, icon);
    }

    void DoInstall() { Apply(false); }

    void DoRestore() {
        string q = "Put the original game back? This removes every mod from the exe, takes Jinn and Cy's portraits out, " +
                   "puts back the stock Sounds.map lines, takes the Executioner rock fix out and binds Enter to Thrust again. " +
                   "SWE1R HD Redraw's own files are left as they are.";
        if (curExe != null && IsIn("extra", curExe))
            q += "\r\n\r\nIf a profile is set to Jinn Reeso or Cy Yunga, pick a stock pilot in the game first. Records set by Jinn or Cy will show the wrong racer.";
        if (Ask(q, Text, MessageBoxButtons.YesNo, MessageBoxIcon.Question) != DialogResult.Yes) return;
        Apply(true);
    }

    [STAThread]
    static void Main(string[] args) {
#if TESTCLI
        // test build only:  /build <game dir> <keys> <out exe>   /install <game dir> <keys>   /restore <game dir>
        // <keys> is a comma list of option keys, or "-" for none
        silent = true;
        if (args.Length == 4 && args[0] == "/build") { Environment.Exit(CliBuild(args[1], args[2], args[3])); return; }
        if (args.Length >= 2 && (args[0] == "/install" || args[0] == "/restore")) {
            var f = new InstallerForm();
            f.folder.Text = args[1]; f.LoadFolder();
            Console.WriteLine("status: " + f.status.Text);
            Console.WriteLine("detected: " + string.Join(",", f.options.Where(o => o.Box.Checked).Select(o => o.Key)));
            if (f.baseExe == null) { Environment.Exit(2); return; }
            if (args[0] == "/restore") f.DoRestore();
            else {
                var keys = args[2].Split(',');
                foreach (var o in f.options) o.Box.Checked = keys.Contains(o.Key);
                f.UpdateEnabled();
                f.DoInstall();
            }
            Console.WriteLine("now: " + string.Join(",", f.options.Where(o => o.Box.Checked).Select(o => o.Key)));
            Environment.Exit(0); return;
        }
#endif
        Application.EnableVisualStyles();
        Application.SetCompatibleTextRenderingDefault(false);
        Application.Run(new InstallerForm());
    }

    // Builds an exe for a key list into a separate file, touching nothing in the game folder.
    static int CliBuild(string dir, string keyList, string outPath) {
        var f = new InstallerForm();
        f.folder.Text = dir; f.LoadFolder();
        if (f.baseExe == null) { Console.Error.WriteLine(f.status.Text); return 2; }
        var keys = keyList.Split(new[] { ',' }, StringSplitOptions.RemoveEmptyEntries);
        foreach (var o in f.options) o.Box.Checked = keys.Contains(o.Key);
        File.WriteAllBytes(outPath, f.BuildExe(new List<string>()));
        return 0;
    }
}
